create or replace function public.claim_agent_runtime_goal(p_goal_id uuid, p_claim_token text) returns boolean language plpgsql security definer set search_path = public as $$ declare claimed boolean; begin update public.agent_runtime_goals set status='running', updated_at=now(), output=jsonb_build_object('_claim', p_claim_token) where id=p_goal_id and status='queued'; get diagnostics claimed = row_count; return claimed; end; $$; grant execute on function public.claim_agent_runtime_goal(uuid,text) to service_role;
